// Cloudflare Worker entry for the Portal (wrangler.jsonc "main"): OpenNext's request handler, plus
// the every-minute cron (meeting reminders and upkeep, show edit approval) and the infocus-show-uploads queue consumer
// that sends shows to YouTube. Both call the Portal's own
// routes in-process, so they need no network hop and no Inngest runs.
// @ts-ignore -- generated by `opennextjs-cloudflare build` (absent until a build has run)
import { default as handler } from "./.open-next/worker.js";
import { MEETING_TICK_TOKEN_ID, signMeetingInternalToken } from "./src/lib/meetings/room-token";
import { meetingTickHasWork } from "./src/lib/meetings/tick-precheck";
import { showEditTickHasWork } from "./src/lib/show-editor-tick-precheck";
import { isLiveOverlayRequest, serveCachedOverlay, type OverlayCache } from "./src/lib/live-overlay-cache";
import { isNextImageRequest, serveCachedImage, type ImageCache } from "./src/lib/next-image-cache";
import { PASSKEY_RP_ID, passkeyRelatedOrigins } from "./src/lib/equipment-kiosk";

type PortalEnv = {
  MEETING_ROOM_SECRET?: string;
  APP_BASE_URL?: string;
  CRON_SECRET?: string;
  SHOW_UPLOADS?: ShowUploadQueue;
  HYPERDRIVE?: { connectionString: string };
};
type WorkerContext = { waitUntil(promise: Promise<unknown>): void; passThroughOnException(): void };

/** POST /api/service/meetings/tick with the internal token the route expects (src/server/meetings-service.ts). */
async function tickMeetings(env: PortalEnv, ctx: WorkerContext) {
  // Most minutes no meeting needs work: answer that with one query instead of loading Next.js.
  // If the check itself fails, run the full tick so nothing is skipped.
  if (env.HYPERDRIVE) {
    const hasWork = await meetingTickHasWork(env.HYPERDRIVE.connectionString).catch((error) => {
      console.error("portal cron: meetings pre-check failed; running the full tick", error);
      return true;
    });
    if (!hasWork) return;
  }
  const secret = env.MEETING_ROOM_SECRET?.trim();
  if (!secret) {
    console.error("portal cron: MEETING_ROOM_SECRET is not set; meetings tick skipped");
    return;
  }
  const token = await signMeetingInternalToken("room", MEETING_TICK_TOKEN_ID, secret);
  const base = (env.APP_BASE_URL?.trim() || "https://infocusportal.com").replace(/\/+$/, "");
  const request = new Request(`${base}/api/service/meetings/tick`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}` }
  });
  const response: Response = await handler.fetch(request, env, ctx);
  if (!response.ok) console.error("portal cron: meetings tick failed", response.status);
}

/** POST /api/service/show-editor/tick (Bearer CRON_SECRET): approval escalation and the 8 AM auto-schedule. */
async function tickShowEdits(env: PortalEnv, ctx: WorkerContext) {
  // Same idea as the meetings pre-check: only load Next.js when an edit is waiting on a show that's close.
  if (env.HYPERDRIVE) {
    const hasWork = await showEditTickHasWork(env.HYPERDRIVE.connectionString).catch((error) => {
      console.error("portal cron: show edit pre-check failed; running the full tick", error);
      return true;
    });
    if (!hasWork) return;
  }
  const secret = env.CRON_SECRET?.trim();
  if (!secret) {
    console.error("portal cron: CRON_SECRET is not set; show edit tick skipped");
    return;
  }
  const base = (env.APP_BASE_URL?.trim() || "https://infocusportal.com").replace(/\/+$/, "");
  const request = new Request(`${base}/api/service/show-editor/tick`, {
    method: "POST",
    headers: { Authorization: `Bearer ${secret}` }
  });
  const response: Response = await handler.fetch(request, env, ctx);
  if (!response.ok) console.error("portal cron: show edit tick failed", response.status);
}

type ShowUploadQueue = { send(body: { id: string }, options?: { delaySeconds?: number }): Promise<void> };
type ShowUploadMessage = { body: { id?: unknown }; ack(): void; retry(options?: { delaySeconds?: number }): void };

/** POST /api/service/shows/upload `{ id }` (app/api/service/shows/upload); returns when to run the show again, or null. */
async function runShowUpload(env: PortalEnv, ctx: WorkerContext, id: string): Promise<number | null> {
  const secret = env.CRON_SECRET?.trim();
  if (!secret) throw new Error("CRON_SECRET is not set");
  const base = (env.APP_BASE_URL?.trim() || "https://infocusportal.com").replace(/\/+$/, "");
  const request = new Request(`${base}/api/service/shows/upload`, {
    method: "POST",
    headers: { Authorization: `Bearer ${secret}`, "Content-Type": "application/json" },
    body: JSON.stringify({ id })
  });
  const response: Response = await handler.fetch(request, env, ctx);
  if (!response.ok) throw new Error(`show upload call failed (${response.status})`);
  const { data } = (await response.json()) as { data?: { nextInSeconds?: number | null } };
  return typeof data?.nextInSeconds === "number" ? data.nextInSeconds : null;
}

export default {
  fetch(request: Request, env: PortalEnv, ctx: WorkerContext): Promise<Response> {
    // WebAuthn related origins: lets infocusportal.com use the equipment passkeys registered on
    // infocuspaly.com (src/lib/equipment-kiosk.ts). Answered here, ahead of the app's sign-in checks.
    const url = new URL(request.url);
    if (url.pathname === "/.well-known/webauthn" && url.hostname === PASSKEY_RP_ID) {
      return Promise.resolve(Response.json({ origins: passkeyRelatedOrigins() }, { headers: { "Cache-Control": "public, max-age=3600" } }));
    }
    // OBS overlay polls: answered from this data center's cache for a couple of seconds (src/lib/live-overlay-cache.ts).
    if (isLiveOverlayRequest(request)) {
      const cache = (caches as unknown as { default: OverlayCache }).default;
      return serveCachedOverlay(request, () => handler.fetch(request, env, ctx), cache, ctx);
    }
    if (!isNextImageRequest(request)) return handler.fetch(request, env, ctx);
    // Resized images: this data center's cache first, so each image is resized once (src/lib/next-image-cache.ts).
    const cache = (caches as unknown as { default: ImageCache }).default;
    return serveCachedImage(request, () => handler.fetch(request, env, ctx), cache, ctx);
  },
  async scheduled(_controller: unknown, env: PortalEnv, ctx: WorkerContext) {
    // One failing never holds up the other.
    const results = await Promise.allSettled([tickMeetings(env, ctx), tickShowEdits(env, ctx)]);
    for (const result of results) {
      if (result.status === "rejected") console.error("portal cron: tick failed", result.reason);
    }
  },
  // Shows upload without cron: confirming queues the show, and each run queues the next one (right
  // away if it ran out of time, a minute later while YouTube processes) until the show is done.
  // max_concurrency 1 and batch size 1 (wrangler.jsonc): one show runs at a time.
  async queue(batch: { messages: ShowUploadMessage[] }, env: PortalEnv, ctx: WorkerContext) {
    for (const message of batch.messages) {
      const id = message.body?.id;
      if (typeof id !== "string" || !id) {
        message.ack();
        continue;
      }
      try {
        const next = await runShowUpload(env, ctx, id);
        if (next !== null) await env.SHOW_UPLOADS!.send({ id }, { delaySeconds: next });
        message.ack();
      } catch (error) {
        console.error("portal: show upload run failed; retrying in a minute", error);
        message.retry({ delaySeconds: 60 });
      }
    }
  }
};

// Durable Objects used by OpenNext's cache (wrangler.jsonc durable_objects).
// @ts-ignore -- generated by `opennextjs-cloudflare build` (absent until a build has run)
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
